// Extract session_id from the FAILED execution's webhook trigger data (deep JSON).
// The Error Trigger payload carries execution.id + lastNodeExecuted + error but NOT the webhook body,
// so the previous node fetched GET /api/v1/executions/{id}?includeData=true.
const resp = $input.first().json;
let data = resp.data;
if (typeof data === 'string') { try { data = JSON.parse(data); } catch (e) { data = null; } }
let sessionId = null;
try {
  const runData = data && data.resultData && data.resultData.runData;
  const trig = runData && runData['🎯 Webhook Trigger'];
  const item = trig && trig[0] && trig[0].data && trig[0].data.main && trig[0].data.main[0] && trig[0].data.main[0][0];
  const body = item && item.json && item.json.body;
  const sid = body && body.session_id;
  sessionId = (typeof sid === 'string' && sid.length > 0) ? sid : null;
} catch (e) { sessionId = null; }
// CLI runs have no session_id -> {session_id: null} -> IF routes to no-op.
// NEVER guess "newest generating row": a concurrent API session could be mis-marked.
const trg = $('Error Trigger').first().json;
const errorStage = (trg.execution && trg.execution.lastNodeExecuted) || null;
const errorMsg = (trg.execution && trg.execution.error && trg.execution.error.message) || null;
return [{ json: { session_id: sessionId, error_stage: errorStage, error_msg: errorMsg } }];
